import json
# Species are curated as a broad regional discovery list, not a complete checklist or occurrence forecast.
groups={
'Backyards & neighborhoods':'''Northern Cardinal|Blue Jay|American Robin|Black-capped Chickadee|Tufted Titmouse|White-breasted Nuthatch|Red-breasted Nuthatch|Downy Woodpecker|Hairy Woodpecker|Red-bellied Woodpecker|Pileated Woodpecker|Northern Flicker|American Goldfinch|House Finch|Purple Finch|Pine Siskin|Common Redpoll|Evening Grosbeak|Rose-breasted Grosbeak|Indigo Bunting|Eastern Bluebird|Gray Catbird|Brown Thrasher|Northern Mockingbird|European Starling|House Sparrow|House Wren|Carolina Wren|Winter Wren|Song Sparrow|Chipping Sparrow|White-throated Sparrow|White-crowned Sparrow|Dark-eyed Junco|Fox Sparrow|Lincoln's Sparrow|Field Sparrow|American Tree Sparrow|Eastern Towhee|Common Grackle|Red-winged Blackbird|Brown-headed Cowbird|Baltimore Oriole|Orchard Oriole|Cedar Waxwing|Bohemian Waxwing|Ruby-throated Hummingbird|Mourning Dove|Rock Pigeon|Eurasian Collared-Dove''',
'Woodlands & bluffs':'''Scarlet Tanager|Summer Tanager|Wood Thrush|Hermit Thrush|Swainson's Thrush|Veery|Eastern Wood-Pewee|Great Crested Flycatcher|Eastern Phoebe|Eastern Kingbird|Least Flycatcher|Yellow-bellied Sapsucker|Red-headed Woodpecker|Black-billed Cuckoo|Yellow-billed Cuckoo|Barred Owl|Great Horned Owl|Eastern Screech-Owl|Northern Saw-whet Owl|Wild Turkey|Ruffed Grouse|American Woodcock|Yellow-throated Vireo|Red-eyed Vireo|Blue-headed Vireo|Warbling Vireo|Philadelphia Vireo|Golden-crowned Kinglet|Ruby-crowned Kinglet|Brown Creeper|Blue-gray Gnatcatcher''',
'Warblers & migrants':'''Yellow Warbler|American Redstart|Blackburnian Warbler|Black-throated Green Warbler|Black-throated Blue Warbler|Black-and-white Warbler|Chestnut-sided Warbler|Magnolia Warbler|Nashville Warbler|Tennessee Warbler|Orange-crowned Warbler|Palm Warbler|Pine Warbler|Yellow-rumped Warbler|Bay-breasted Warbler|Blackpoll Warbler|Cape May Warbler|Canada Warbler|Wilson's Warbler|Hooded Warbler|Prothonotary Warbler|Cerulean Warbler|Ovenbird|Northern Waterthrush|Louisiana Waterthrush|Common Yellowthroat|Mourning Warbler|Connecticut Warbler|Golden-winged Warbler|Blue-winged Warbler|Northern Parula|Yellow-breasted Chat''',
'Rivers, lakes & wetlands':'''Wood Duck|Mallard|American Black Duck|Northern Pintail|Northern Shoveler|Blue-winged Teal|Green-winged Teal|Gadwall|American Wigeon|Canvasback|Redhead|Ring-necked Duck|Lesser Scaup|Greater Scaup|Bufflehead|Common Goldeneye|Hooded Merganser|Common Merganser|Red-breasted Merganser|Ruddy Duck|Canada Goose|Cackling Goose|Snow Goose|Trumpeter Swan|Tundra Swan|American White Pelican|Double-crested Cormorant|Great Blue Heron|Great Egret|Green Heron|Black-crowned Night Heron|American Bittern|Least Bittern|Sandhill Crane|Whooping Crane|Pied-billed Grebe|Horned Grebe|Red-necked Grebe|American Coot|Common Gallinule|Sora|Virginia Rail|Belted Kingfisher|Osprey|Bald Eagle|Ring-billed Gull|Herring Gull|Bonaparte's Gull|Forster's Tern|Common Tern|Black Tern|Caspian Tern''',
'Shorebirds & grasslands':'''Killdeer|Spotted Sandpiper|Solitary Sandpiper|Greater Yellowlegs|Lesser Yellowlegs|Least Sandpiper|Pectoral Sandpiper|Semipalmated Sandpiper|Dunlin|Wilson's Snipe|American Avocet|Upland Sandpiper|Long-billed Dowitcher|Short-billed Dowitcher|Bobolink|Eastern Meadowlark|Western Meadowlark|Dickcissel|Grasshopper Sparrow|Henslow's Sparrow|Savannah Sparrow|Vesper Sparrow|Clay-colored Sparrow|Sedge Wren|Marsh Wren|Horned Lark|American Pipit|Lapland Longspur|Snow Bunting''',
'Raptors & aerial birds':'''Red-tailed Hawk|Red-shouldered Hawk|Broad-winged Hawk|Cooper's Hawk|Sharp-shinned Hawk|Northern Harrier|Rough-legged Hawk|Swainson's Hawk|Peregrine Falcon|American Kestrel|Merlin|Turkey Vulture|Black Vulture|Northern Goshawk|Short-eared Owl|Long-eared Owl|Snowy Owl|Chimney Swift|Common Nighthawk|Eastern Whip-poor-will|Tree Swallow|Barn Swallow|Cliff Swallow|Bank Swallow|Northern Rough-winged Swallow|Purple Martin'''
}
seasonal={'winter':['Snow Bunting','Common Redpoll','Bohemian Waxwing','Rough-legged Hawk','Snowy Owl','American Tree Sparrow','Dark-eyed Junco','Lapland Longspur','Common Goldeneye','Bufflehead','Tundra Swan','Pine Siskin','Evening Grosbeak','Northern Shrike'],'summer':['Ruby-throated Hummingbird','Baltimore Oriole','Orchard Oriole','Indigo Bunting','Scarlet Tanager','Rose-breasted Grosbeak','Bobolink','Dickcissel','Eastern Kingbird','Chimney Swift','Common Nighthawk','Purple Martin','American Redstart','Yellow Warbler','Prothonotary Warbler','Cerulean Warbler','Wood Thrush','Veery','Eastern Wood-Pewee','Great Crested Flycatcher']}
rare=set('Whooping Crane|American Avocet|Swainson\'s Hawk|Black Vulture|Summer Tanager|Connecticut Warbler|Hooded Warbler|Western Meadowlark|Northern Goshawk|Bohemian Waxwing|Snowy Owl|Northern Shrike|Greater Scaup|Black-crowned Night Heron|Least Bittern'.split('|'))
seasonal_only=set('Snow Bunting|Common Redpoll|Bohemian Waxwing|Rough-legged Hawk|Snowy Owl|Lapland Longspur|Tundra Swan|Northern Shrike'.split('|'))
latin={'Cedar Waxwing':'Bombycilla cedrorum','Northern Cardinal':'Cardinalis cardinalis','Blue Jay':'Cyanocitta cristata','American Robin':'Turdus migratorius','Scarlet Tanager':'Piranga olivacea','Snow Bunting':'Plectrophenax nivalis','Wood Duck':'Aix sponsa','Blackburnian Warbler':'Setophaga fusca','Northern Saw-whet Owl':'Aegolius acadicus','American White Pelican':'Pelecanus erythrorhynchos','Bald Eagle':'Haliaeetus leucocephalus','Sandhill Crane':'Antigone canadensis','Ruby-throated Hummingbird':'Archilochus colubris','Great Blue Heron':'Ardea herodias','Eastern Bluebird':'Sialia sialis','Pileated Woodpecker':'Dryocopus pileatus','Baltimore Oriole':'Icterus galbula','Rose-breasted Grosbeak':'Pheucticus ludovicianus','Common Loon':'Gavia immer'}
facts={'Cedar Waxwing':'Look for a sleek crest, black eye mask, and yellow-tipped tail; flocks often gather in berry trees.','Scarlet Tanager':'The breeding male glows scarlet red with black wings, often high in leafy forest canopies.','Snow Bunting':'A hardy Arctic breeder that visits open fields and roadsides in winter flocks.','Wood Duck':'A spectacularly patterned duck that nests in tree cavities near wooded water.','Blackburnian Warbler':'The male’s fiery orange throat is especially striking during spring migration.','Northern Saw-whet Owl':'A tiny, secretive owl that can spend daylight hours hidden in dense conifers.','American White Pelican':'Huge white birds with black flight feathers often soar together above the Mississippi.','Bald Eagle':'Watch for broad, flat wings and powerful soaring over the river; adults have white heads and tails.','Sandhill Crane':'Tall gray cranes with a red crown, famous for their rolling, bugling calls.','Ruby-throated Hummingbird':'Our familiar summer hummingbird; the male flashes a ruby-red throat in the right light.','Great Blue Heron':'A tall, patient hunter that stalks fish and frogs in shallow water.','Pileated Woodpecker':'A crow-sized woodpecker with a dramatic red crest; look for large rectangular holes in trees.','Baltimore Oriole':'A brilliant orange-and-black summer visitor that weaves a hanging pouch nest.','Rose-breasted Grosbeak':'The male has a vivid red chest patch and a powerful pale bill.','Whooping Crane':'Exceptionally rare in the region; any apparent sighting deserves careful verification.','Cedar Waxwing':'A silky-crested bird with a black mask and yellow tail tip, often seen in berry-feeding flocks.'}
bygroup={'Backyards & neighborhoods':('Neighborhoods & feeders','Look for this species around trees, yards, hedges, parks, and neighborhood edges.'),'Woodlands & bluffs':('Forests & bluffs','Search woodland edges, wooded ravines, and the bluffs of the Driftless Area.'),'Warblers & migrants':('Forest & migration','During migration, watch for quick movements among leaves and branches.'),'Rivers, lakes & wetlands':('Rivers & wetlands','Check the Mississippi River, backwaters, marshes, and open water.'),'Shorebirds & grasslands':('Fields & shorelines','Scan open fields, prairie habitat, mudflats, and wet meadow edges.'),'Raptors & aerial birds':('Sky & open country','Look overhead, along treelines, and above fields or river corridors.')}
birds=[]
for group, names in groups.items():
 for name in names.split('|'):
  habitat,default=bygroup[group]
  if name in seasonal['winter'] or name in seasonal_only: seasons=['fall','winter','spring']
  elif name in seasonal['summer'] or group=='Warblers & migrants':seasons=['spring','summer','fall']
  elif group=='Rivers, lakes & wetlands':seasons=['spring','summer','fall','winter']
  elif group=='Shorebirds & grasslands':seasons=['spring','summer','fall']
  else:seasons=['spring','summer','fall','winter']
  rarity='Rare / unusual' if name in rare else 'Seasonal visitor' if len(seasons)<4 else 'Regional species'
  birds.append(dict(name=name,latin=latin.get(name,''),habitat=habitat,fact=facts.get(name,default),seasons=seasons,rarity=rarity))
# Some species occur only in migration or with irregular timing; labels are intentionally approximate.
with open('/mnt/data/BirdClock/birds.js','w') as f:f.write('const birds = '+json.dumps(birds,ensure_ascii=False,separators=(',',':'))+';\n')
print(len(birds))
